design_text:
{
  "site_summary": "A partial shade balcony with high moisture from a rain barrel, hosting a curious cat and a dog in a safe environment.",
  "layout_strategy": "The scheme stacks in three distinct height layers, featuring trailing ferns on high brackets, structural shrubs and aromatic herbs at mid-level against the wall, and a dense, low groundcover layer along the floor.",
  "combination_logic": "The design contrasts the broad, patterned leaves of prayer plants with the fine, textured fronds of ball ferns and the upright, mounding forms of hydrangeas and herbs. This creates a lush tropical woodland aesthetic that shifts from vibrant green foliage in spring to striking blooms in summer and textural dormancy in winter.",
  "zones": [
    {
      "zone_name": "Canopy Ferns",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On high wall hooks, 6 feet up, receiving dappled partial shade and sheltered from heavy winds.",
      "plants": [
        {
          "scientific_name": "Davallia spp.",
          "common_name": "Ball Fern",
          "why": "Thrives in high moisture and partial shade, providing a wonderful trailing habit.",
          "role_in_combination": "Contributes fine-textured, feathery green fronds that cascade downwards, contrasting with the rigid structural plants below."
        }
      ],
      "maintenance": [
        "Water thoroughly twice a week in summer, ensuring the fuzzy rhizomes do not dry out completely.",
        "Feed with a half-strength balanced liquid fertilizer monthly during spring and summer.",
        "Prune away any dead or brown fronds at the base in late winter."
      ]
    },
    {
      "zone_name": "Structural Shrub and Herb Wall",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "Against the back wall in large containers, receiving partial shade and indirect moisture runoff.",
      "plants": [
        {
          "scientific_name": "Hydrangea arborescens",
          "common_name": "Hydrangea",
          "why": "Loves high moisture and partial shade, creating a dramatic focal point.",
          "role_in_combination": "Provides large, rounded flower heads and broad leaves that contrast starkly with the finer foliage in the design."
        },
        {
          "scientific_name": "Calathea insignis",
          "common_name": "Prayer Plant",
          "why": "Prefers the humid, shaded conditions created by the nearby rain barrel.",
          "role_in_combination": "Adds exotic leaf pattern and deep burgundy undersides for rich colour contrast at mid-height."
        }
      ],
      "maintenance": [
        "Water daily during peak summer heat to satisfy the high moisture requirement of the hydrangeas.",
        "Prune hydrangea stems back in early spring to encourage vigorous new flowering wood.",
        "Repot every two years in fresh, well-draining organic compost."
      ]
    },
    {
      "zone_name": "Pet Grazing Patch",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "On the balcony floor near the entrance, fully accessible to the cat and dog in partial shade.",
      "plants": [
        {
          "scientific_name": "Melissa officinalis",
          "common_name": "Lemon Balm",
          "why": "A vigorous, moisture-loving herb that is safe and appealing for pets to brush against.",
          "role_in_combination": "Releases a calming citrus scent when brushed against and offers a bright green, textured ground element."
        },
        {
          "scientific_name": "Mentha sp.",
          "common_name": "Mint",
          "why": "Thrives in soggy soil conditions and grows rapidly in low light.",
          "role_in_combination": "Provides a lush, mat-forming green ground layer that contrasts in leaf shape with the lemon balm."
        }
      ],
      "maintenance": [
        "Keep the soil constantly moist using water directly from the rain barrel.",
        "Cut back vigorously after summer flowering to encourage fresh, tender growth for the pets.",
        "Divide root clumps every spring to prevent the pots from becoming overcrowded."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers using rain barrel water",
      "frequency": "Daily in summer, twice a week in spring and autumn",
      "season": "Summer"
    },
    {
      "task": "Apply organic liquid fertilizer to mid-layer and vertical plants to support lush foliage growth",
      "frequency": "Monthly",
      "season": "Spring"
    },
    {
      "task": "Clear away fallen dead leaves and debris from the ground layer to prevent fungal issues in high humidity",
      "frequency": "Weekly",
      "season": "Autumn"
    }
  ],
  "care_cautions": [
    "Overwatering and root rot may occur in the Ball Fern hanging basket if drainage holes become blocked.",
    "The Solanum dulcamara (Climbing Nightshade) from the catalogue was intentionally excluded due to its high toxicity to the household cat and dog.",
    "High moisture around the ground layer can attract slugs to the Hydrangea and Calathea foliage during damp autumns."
  ],
  "pet_safety_note": "Toxic and dangerous plants like Climbing Nightshade have been omitted, and the designated grazing zone provides safe, aromatic herbs (Mint and Lemon Balm) that satisfy the cat's urge to chew without causing harm."
}
